examples.code:
#include <flat_map>
#include <vector>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::flat_multimap<int, int> values;
    values.insert({2, 20});
    values.emplace(1, 10);
    values.emplace_hint(values.end(), 3, 30);
    assert(values.count(2) == 1 && values.lower_bound(2) != values.end() &&
        values.upper_bound(2) != values.begin());
    std::flat_multimap<int, int> copy = values;
    assert(copy == values);
    copy.swap(values);
    std::swap(copy, values);
    auto compare = values.value_comp();
    assert(compare({1, 10}, {2, 20}));
    std::flat_multimap deduced{std::vector<int>{1, 2}, std::vector<int>{10, 20}};
    assert(deduced.size() == 2);
    std::flat_multimap<int, int> sorted{
        std::sorted_equivalent, std::vector<int>{1, 2}, std::vector<int>{10, 20}};
    assert(sorted.size() == 2);
}
